<?php require_once __DIR__.'/app/bootstrap.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('booking.php'); $required=['name','email','mobile','country','package_name','airport_pickup','arrival_date','departure_date','adults']; foreach($required as $f) if(trim($_POST[$f]??'')==='') { $_SESSION['flash']=['type'=>'danger','msg'=>'Please complete all required fields.']; redirect('booking.php'); } $b=['id'=>next_id(read_data('bookings')),'name'=>trim($_POST['name']),'email'=>trim($_POST['email']),'mobile'=>trim($_POST['mobile']),'country'=>trim($_POST['country']),'package_name'=>trim($_POST['package_name']),'airport_pickup'=>trim($_POST['airport_pickup']),'arrival_date'=>$_POST['arrival_date'],'departure_date'=>$_POST['departure_date'],'adults'=>(int)$_POST['adults'],'children'=>(int)($_POST['children']??0),'message'=>trim($_POST['message']??''),'status'=>'New','booking_date'=>date('Y-m-d H:i:s')]; $items=read_data('bookings'); $items[]=$b; write_data('bookings',$items); $_SESSION['flash']=['type'=>'success','msg'=>'Booking submitted successfully. Our team will contact you soon.']; redirect('booking.php');